eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   awards: () => (/* binding */ awards),\n/* harmony export */   companyInfo: () => (/* binding */ companyInfo),\n/* harmony export */   companyValues: () => (/* binding */ companyValues),\n/* harmony export */   expertiseAreas: () => (/* binding */ expertiseAreas),\n/* harmony export */   heroContent: () => (/* binding */ heroContent),\n/* harmony export */   safetyProgram: () => (/* binding */ safetyProgram),\n/* harmony export */   serviceCards: () => (/* binding */ serviceCards),\n/* harmony export */   stats: () => (/* binding */ stats),\n/* harmony export */   testimonials: () => (/* binding */ testimonials),\n/* harmony export */   timelineEntries: () => (/* binding */ timelineEntries)\n/* harmony export */ });\nconst heroContent = {\n    title: 'DD&B CONSTRUCTION',\n    subtitle: 'Full-service general contracting built on hard work, honest business practices, and a desire to achieve since 1981.',\n    description: \"Ground up commercial builders and general contractors with the expertise and financial stability to complete the project every time. That is DD&B Construction's legacy for almost 40 years. With every commercial building construction project, our goal is effective communication, reliability, and safety.\",\n    ctaText: 'Discuss Your Project',\n    backgroundImage: '/images/DD&B Website Pics/Hampton San Antonio Lackland SeaWorld/SATLP-BWD_TX_SATSEA_HIS_EXT_DUSK.jpg'\n};\nconst serviceCards = [\n    {\n        title: 'General Contractor Services',\n        blurb: 'DD&B knows what is important to clients: Communication. Expertise. Reliability. Financial stability. Honesty. And quality work. We offer budgeting & value-engineering, flexible contract types, full supervision, and on-time/on-budget delivery.',\n        img: '/images/exterior/SATWO_TX_SATWESTOVER_RI_EXTERIOR_DAY.jpg'\n    },\n    {\n        title: 'Hotel Construction',\n        blurb: 'DD&B Construction is the general contractor of choice for many companies in the hospitality industry. Our exacting standards and 100% completion record since 1981 gives clients confidence that their hotel construction project will be successfully completed to their satisfaction every time.',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_LOBBY1.jpg'\n    },\n    {\n        title: 'Multi-Family Residential',\n        blurb: 'We are turn-key builders of apartments, condos, and buildings designed for mixed-use. These projects must be constructed with the needs of the people and families that will eventually live in them. We take great pride in building comfortable, safe homes.',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_130_STDOAX_ADAKING_KITCHEN.jpg'\n    },\n    {\n        title: 'Ground-Up Construction',\n        blurb: \"DD&B Construction delivers turn-key commercial construction services that take a project from the planning stages through site preparation, construction and finish-out. We are there to ensure our clients' total satisfaction through their move-in day.\",\n        img: '/images/exterior/SATWO_TX_SATWESTOVER_RI_EXTERIOR_DUSK.jpg'\n    },\n    {\n        title: 'Modular Construction',\n        blurb: 'Clients who need construction completed within a strict timeframe often opt for modular construction methods. DD&B has extensive experience with site preparation and assembly of modular components. Our final product is a commercial building that offers everything expected from traditional methods—in less time.',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_LOBBY2.jpg'\n    },\n    {\n        title: 'High-Rise Construction',\n        blurb: 'High-rise construction is a distinct expertise, and one for which DD&B Construction has experience and proven proficiency. Multi-family high rises, office buildings, hotels, and mixed-use construction are in our portfolio. Clients know they can rely on us for good advice based upon 40 years as commercial builders.',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_MEETINGROOM_CLASS.jpg'\n    },\n    {\n        title: 'Renovation & Restoration',\n        blurb: 'DD&B has the experience and skill to tackle commercial building renovation and restoration of all kinds, including historic renovations and fire / weather-damage restorations, working with insurance companies and permitting agencies as needed.',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_LOBBY2.jpg'\n    },\n    {\n        title: 'Interior Fit-Outs & Finishes',\n        blurb: 'Interior finish work and fit-outs are often subcontracted to DD&B Construction. We are known for our attention to detail and our desire to see clients and their tenants totally satisfied with the completed work.',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_MEETINGROOM_CLASS.jpg'\n    },\n    {\n        title: 'Office & Retail Construction',\n        blurb: 'Creating a safe, comfortable, and energy-efficient place to transact business is beneficial to the owners of the buildings we construct, as well as tenants and their customers. Good communication is the key to meeting the needs of the many stakeholders involved.',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_LOBBY1.jpg'\n    },\n    {\n        title: 'Civic / School / Church',\n        blurb: 'DD&B Construction is proud of the work we have done to improve communities across the nation. We have been selected as the general contractor for numerous government contracts and have built schools and other civic structures that serve residents. We have also built churches and places of worship in many cities.',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_MEETINGROOM_CLASS.jpg'\n    }\n];\nconst timelineEntries = [\n    {\n        year: '1971',\n        title: 'Dolat Mehta Arrives in America',\n        description: 'Dolat Mehta, a civil engineer from India, first arrived in the United States and began working his way up through the competitive D.C. construction industry—from foreman to superintendent, project manager, and eventually Vice President at a leading firm.'\n    },\n    {\n        year: '1981',\n        title: 'DD&B Construction Founded',\n        description: 'Three investors named Dolat, Doug & Buford formed DD&B in 1981. Work began small in the Maryland region, but never slow. Within a few years, DD&B had moved from single-story renovations and basement interiors to school construction, major hospitality construction, and government contracts.'\n    },\n    {\n        year: 'Mid-1980s',\n        title: 'Mr. Mehta Takes Control',\n        description: \"Mr. Mehta bought out the initial partners and set the company's sights on regional expansion, focusing on building the company's reputation for quality work and reliable project completion.\"\n    },\n    {\n        year: '1990s',\n        title: 'Regional Expansion',\n        description: 'Throughout the 1990s DD&B extended into Virginia, New Jersey, Washington D.C., Pennsylvania, and Delaware, establishing the company as a trusted contractor throughout the Mid-Atlantic region.'\n    },\n    {\n        year: 'Today',\n        title: 'A Foundation of Achievement',\n        description: 'DD&B Construction is built on a foundation of hard work, honest business practices, and a desire to achieve. With over 40 years of experience, we maintain our legacy of expertise and financial stability to complete every project.'\n    }\n];\nconst testimonials = [\n    {\n        quote: 'I have worked closely with DD&B Construction for the past 12+ years on various hotel projects. Their input and cooperation have been indispensable to our efforts. We are looking forward to working with them in the future on many more projects to come.',\n        author: 'Shakila Biswas',\n        role: 'Owner',\n        company: 'Design360Architecture',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_MEETINGROOM_CLASS.jpg'\n    },\n    {\n        quote: 'Working with Chintan Patel and his experienced and knowledgeable team, we have successfully completed complex hospitality projects across the midwestern states. The DD&B team provided seamless project management, cost-effective solutions, and on-time delivery.',\n        author: 'Greg T. Shue, AIA',\n        role: 'Principal',\n        company: 'Open Studio Architecture',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_FRONTDESK.jpg'\n    },\n    {\n        quote: 'The DD&B team has developed a solid understanding of the various Hilton Brands. Their past performance including the quality of the work, service to owners and advocacy of our brands has been fantastic.',\n        author: 'Peter Rudewicz',\n        role: 'VP, Focused Service Brands',\n        company: 'Hilton Hotels',\n        img: '/images/interior/SATWO_TX_SATWESTOVER_RI_LOBBY2.jpg'\n    }\n];\nconst stats = [\n    {\n        value: '43',\n        label: 'Years Building Quality',\n        suffix: '+'\n    },\n    {\n        value: '100',\n        label: 'Project Completion Rate',\n        suffix: '%'\n    },\n    {\n        value: '8',\n        label: 'States Served',\n        suffix: ''\n    },\n    {\n        value: '2',\n        label: 'Regional Offices',\n        suffix: ''\n    }\n];\nconst safetyProgram = [\n    {\n        title: 'Safety Training Foundation',\n        description: 'Our commitment to safety is readily apparent from the moment someone enters our offices or job site. Our team leads by example, setting standards and defining best practices for our employees and subs. The focus on safety has led to a culture of safety first in our management activity and enforcement.',\n        points: [\n            'Safety training is the foundation of our program',\n            'Consistent communication and at least monthly safety inspections',\n            'Third-party safety inspectors ensure highest level of job-site safety',\n            'All direct labor, supervisors, and project-management teams safety-trained'\n        ]\n    },\n    {\n        title: 'OSHA Compliance & Requirements',\n        description: 'All direct labor, supervisors, and project-management teams, as well as subcontractors, are required to be safety-trained and adhere to OSHA rules and requirements.',\n        points: [\n            'Comprehensive OSHA safety training for all personnel',\n            'Subcontractor safety training requirements',\n            'Strict adherence to OSHA rules and regulations',\n            'Regular safety updates and certifications'\n        ]\n    },\n    {\n        title: 'LEED & Sustainable Construction',\n        description: \"DD&B Construction works with our clients' architects and engineers to ensure a smooth construction process while meeting project sustainability requirements. Whether the project is LEED-certified or not, we know that sustainable buildings are now the norm.\",\n        points: [\n            'LEED-certified project experience',\n            'Green building construction expertise',\n            'Sustainable construction practices',\n            'Collaboration with architects and engineers on sustainability'\n        ]\n    }\n];\n// New content for additional sections\nconst expertiseAreas = [\n    {\n        title: 'Hotel Construction',\n        description: 'Specialized expertise in hospitality construction from ground-up development to renovations for major brands like Marriott, Hilton, Hyatt and IHG.',\n        icon: '🏨',\n        projects: 'Extensive portfolio of hotel projects'\n    },\n    {\n        title: 'Multi-Family Construction',\n        description: 'Apartments, condominiums and residential complexes, including a 200‑unit development in Manor, Texas.',\n        icon: '🏢',\n        projects: 'Trusted partner for multifamily developers'\n    },\n    {\n        title: 'Commercial Office Buildings',\n        description: 'Professional office buildings, retail centers and mixed-use developments across the Mid-Atlantic and Texas.',\n        icon: '🏢',\n        projects: 'Dozens of commercial projects delivered'\n    },\n    {\n        title: 'Civic & Religious Buildings',\n        description: 'Schools, churches and civic buildings including public schools in Maryland and temple projects.',\n        icon: '🏛️',\n        projects: 'Experienced civic and religious builder'\n    },\n    {\n        title: 'High Rise Construction',\n        description: 'Multi-story commercial buildings with complex structural requirements.',\n        icon: '🏗️',\n        projects: 'Proven high‑rise expertise'\n    },\n    {\n        title: 'Modular Construction',\n        description: 'Innovative modular construction techniques for efficient project delivery.',\n        icon: '🔧',\n        projects: 'Modular solutions for accelerated schedules'\n    }\n];\nconst companyInfo = {\n    tagline: 'A Foundation of Achievement',\n    description: 'DD&B Construction is built on a foundation of hard work, honest business practices, and a desire to achieve. Ground up commercial builders and general contractors with the expertise and financial stability to complete the project every time.',\n    goals: 'With every commercial building construction project, our goal is effective communication, reliability, and safety.',\n    specialties: 'DD&B Construction has made a name for itself for its work in hotel construction, multi-family construction of apartments and condos, the construction of schools, churches and other religious buildings, and commercial building construction, including retail centers and office buildings.',\n    founder: 'The company was founded by Dolat Mehta, a civil engineer from India who first arrived in the United States in 1971.',\n    regions: 'Serving the Mid-Atlantic region including Maryland, Virginia, New Jersey, Washington D.C., Pennsylvania, and Delaware',\n    headquarters: '17B Firstfield Road, Suite #203, Gaithersburg, Maryland 20878',\n    westOffice: '7300 Blanco Road, Suite 708, San Antonio, Texas 78216',\n    phonesMD: '301-869-8415',\n    phoneTX: '210-298-4499'\n};\n// Awards and Recognition\nconst awards = [\n    {\n        title: 'Best Hotel Contractors in San Antonio',\n        year: '2021',\n        description: 'Recognized by SanAntonioArchitects.org for excellence in hospitality construction'\n    },\n    {\n        title: 'Bonding Agent Endorsement',\n        year: '1984–Present',\n        description: 'Marsh & McLennan notes DD&B has never had a bond request declined'\n    },\n    {\n        title: '40+ Years of Excellence',\n        year: '1981–Present',\n        description: 'Over four decades of quality construction across multiple states'\n    },\n    {\n        title: '100% Completion Rate',\n        year: 'Ongoing',\n        description: 'Maintained a perfect project completion record'\n    }\n];\n// Company Culture and Values\nconst companyValues = [\n    {\n        title: 'Communication',\n        description: 'DD&B knows what is important to clients: Communication. Clear, consistent communication throughout every project.'\n    },\n    {\n        title: 'Expertise',\n        description: 'Over 40 years of construction expertise and proven proficiency across multiple sectors and building types.'\n    },\n    {\n        title: 'Reliability',\n        description: 'Financial stability and 100% project completion record ensures reliable project delivery every time.'\n    },\n    {\n        title: 'Quality Work',\n        description: 'Honest business practices and a desire to achieve excellence in every commercial construction project.'\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/content.ts\n");

